import{_ as o,o as s,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Crimson/Seastar OSD 2018-10-30","description":"","frontmatter":{"title":"Crimson/Seastar OSD 2018-10-30","date":"2018-10-30T00:00:00.000Z","updated":"2018-11-02T00:00:00.000Z","tags":["Ceph","分布式存储","OSD 优化","内存存储优化","RocksDB 集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_2018-10-30.md","filePath":"posts/2018/Crimson_Seastar_OSD_2018-10-30.md","lastUpdated":1780460162000}'),i={name:"posts/2018/Crimson_Seastar_OSD_2018-10-30.md"};function n(e,t,p,a,g,_){return s(),r("div",null,[...t[0]||(t[0]=[l("<p>会议纪要</p><p>会议时间：2018年10月30日</p><p>会议地点：线上会议</p><p>参会人员：Doritos、Paul、Adam Koochick、Co her、Tara、Kelsey、Whitney、Red Oak、Mission、Rider、Dragon、Cool 等</p><p>会议主题：Ceph 分布式存储系统相关议题讨论</p><p>会议内容：</p><ol><li><p><strong>会议时间调整</strong>： 由于时区差异，会议时间进行了调整。原定于两周后的会议将提前一周举行，并比原计划提前一小时开始。</p></li><li><p><strong>Ceph 当前 OSD 优化</strong>：</p><ul><li><strong>目标</strong>： 降低 OSD 逻辑复杂度，提高性能。</li><li><strong>方法</strong>： 通过优化数据依赖关系，减少不必要的路径，简化操作流程。</li><li><strong>方向</strong>： 从读取操作入手，尝试在复制的存储桶中进行优化。</li><li><strong>难点</strong>： 解决多线程访问、锁冲突等问题。</li><li><strong>实施计划</strong>： 确定优化代码范围，针对读取操作进行优化，逐步扩展到其他操作。</li></ul></li><li><p><strong>Ceph 内存存储优化</strong>：</p><ul><li><strong>目标</strong>： 降低内存存储的复杂度，提高性能。</li><li><strong>方法</strong>： 使用 SISTAR 等技术简化内存存储的读写操作。</li><li><strong>难点</strong>： 解决多线程访问、锁冲突等问题，保证数据一致性。</li><li><strong>实施计划</strong>： 评估 SISTAR 技术的可行性，确定结合方式，测试和优化。</li></ul></li><li><p><strong>Ceph 与 RocksDB 集成</strong>：</p><ul><li><strong>目标</strong>： 将 RocksDB 集成到 Ceph 中，提高性能和可靠性。</li><li><strong>方法</strong>： 使用 SISTAR 等技术简化 RocksDB 的读写操作。</li><li><strong>难点</strong>： 解决多线程访问、锁冲突等问题，保证数据一致性。</li><li><strong>实施计划</strong>： 评估 SISTAR 技术的可行性，确定结合方式，测试和优化。</li></ul></li><li><p><strong>其他事项</strong>：</p><ul><li><strong>会议频率</strong>： 建议将会议频率调整为每周一次。</li><li><strong>项目进度</strong>： 各项目负责人汇报项目进度，并讨论后续工作计划。</li></ul></li></ol><p>后续行动计划：</p><ol><li>各项目负责人根据会议讨论结果，制定详细的实施计划。</li><li>定期召开会议，跟踪项目进度，解决问题。</li><li>及时分享项目进展，促进团队协作。</li></ol>",9)])])}const d=o(i,[["render",n]]);export{c as __pageData,d as default};
